import test from 'node:test';
import assert from 'node:assert/strict';
import {JSDOM} from 'jsdom';
import {purchaseSelection,mountMemberPlans,mountMemberCheckout,mountCommerce,writingBundles} from '../dist/workspace/membership-purchase.mjs';
import {servicePricingEntry} from '../dist/workspace/service-pricing.mjs';
import {specialistBundleOffers} from '../dist/workspace/specialist-commercial-offers.mjs';
const catalogue=()=>({enabled:true,channels:[{provider:'wechat',ready:true},{provider:'alipay',ready:true}],products:[200,500,1000].map(n=>({id:`credits-${n}`,status:'active',currency:'CNY',priceCents:n*10,entitlementType:'credits',creditAmount:n,entitlement:{type:'credits',creditAmount:n}}))});
const memberProduct=(id,overrides={})=>({id,title:`${id} 会员`,description:'后台发布的会员服务说明。',status:'active',currency:'CNY',priceCents:2899,durationDays:45,entitlementType:'membership',membershipItems:[{key:'review',title:'导师意见修改',quantity:10}],entitlement:{type:'membership',durationDays:45},...overrides});
const settle=()=>new Promise(resolve=>setImmediate(resolve));
const setup=()=>{const dom=new JSDOM('<main class="dashboard"></main>',{url:'http://localhost/workspace.html#membership/plans'});for(const key of ['window','document','localStorage','location'])globalThis[key]=dom.window[key];dom.requests=[];dom.window.fetch=async(url,options)=>{dom.requests.push({url,...options});return {ok:true,json:async()=>catalogue()};};return dom;};
test('live membership catalogue paints at the latest viewport and restores the matching offer focus',async()=>{
 const dom=setup();let finish,y=800;const scrolls=[];dom.window.fetch=async()=>new Promise(resolve=>{finish=resolve;});Object.defineProperty(window,'scrollY',{configurable:true,get:()=>y});window.scrollTo=options=>{scrolls.push(options);y=options.top;};
 try{
  mountMemberPlans();await settle();const root=document.querySelector('.dashboard');root.getBoundingClientRect=()=>({top:100-y,left:0,width:1200,height:2400});const pending=document.querySelector('[data-commerce-offer="member:reading-v1"]');assert.ok(pending);pending.focus({preventScroll:true});y=1200;
  const options=catalogue();options.products.push(memberProduct('reading-v1'));finish({ok:true,json:async()=>options});await settle();const live=document.querySelector('[data-member-product="reading-v1"] [data-commerce-offer="member:reading-v1"]');assert.ok(live);assert.notEqual(live,pending);assert.equal(document.activeElement,live);assert.equal(y,1200);assert.equal(scrolls.length,0);assert.match(root.style.minHeight,/1868px/);assert.equal(dom.requests.length,0);assert.equal(localStorage.length,0);
 }finally{dom.window.close();}
});
test('benchmark prices do not become live billing prices; quantity normalized',()=>{const s=purchaseSelection('professional-v1',3);assert.equal(s.referencePrice,69.9);assert.equal(s.quantity,3);assert.equal(s.price,null);assert.equal(s.paymentEnabled,false);for(const n of [0,-1,366,1.5,'foo'])assert.equal(purchaseSelection('x',n).quantity,1);assert.equal(purchaseSelection('dual',2,'bundle').referencePrice,99);});
test('the unified price entry opens a separate catalogue without reading or changing saved drafts',()=>{const dom=setup();localStorage.setItem('paperknow-drafts','[{"id":"test"}]');document.querySelector('.dashboard').innerHTML=servicePricingEntry(document);assert.ok(document.querySelector('a[href="#membership/pricing"]'));assert.doesNotMatch(document.querySelector('.dashboard').textContent,/本地内容|账户内容|备份/);assert.equal(localStorage.getItem('paperknow-drafts'),'[{"id":"test"}]');dom.window.close();});
test('launch member tiers show exact proposed prices and periods without claiming publication',()=>{const dom=setup();mountMemberPlans();assert.equal(document.querySelectorAll('.purchase-plan').length,3);assert.equal(document.querySelectorAll('.commerce-tabs a').length,3);assert.doesNotMatch(document.querySelector('.dashboard').textContent,/¥10/);assert.match(document.querySelector('.dashboard').textContent,/¥29\.9/);assert.match(document.querySelector('.dashboard').textContent,/¥69\.9/);assert.match(document.querySelector('.dashboard').textContent,/建议价 \/ 30 天 · 未上架/);assert.match(document.querySelector('.dashboard').textContent,/60 次/);assert.equal(localStorage.length,0);dom.window.close();});
test('published membership cards use server identities, exact price and duration with escaped descriptions',async()=>{const dom=setup(),options=catalogue();options.products.push(memberProduct('basic',{title:'基础会员 <img src=x>',description:'仅提供当前说明中的服务。\n<script>测试文本</script>'}),memberProduct('advanced'),memberProduct('premium'));dom.window.fetch=async(url,request)=>{dom.requests.push({url,...request});return {ok:true,json:async()=>options};};localStorage.setItem('paperknow-drafts','[{"id":"preserved"}]');mountMemberPlans();await settle();assert.equal(document.querySelectorAll('.purchase-plan').length,4);assert.deepEqual([...document.querySelectorAll('[data-member-product]')].map(p=>p.dataset.memberProduct),['basic','advanced','premium']);const card=document.querySelector('[data-member-product="basic"]');assert.equal(card.querySelector('h3').textContent,'基础会员 <img src=x>');assert.match(card.querySelector('.purchase-price').textContent,/¥28\.99.*45 天/);assert.equal(card.querySelector('.commerce-member-description').textContent,'仅提供当前说明中的服务。\n<script>测试文本</script>');assert.equal(card.querySelector('a.btn').getAttribute('href'),'#membership/pay?product=basic');assert.equal(card.querySelector('a.btn').textContent.trim(),'确认购买');assert.equal(card.querySelector('img'),null);assert.equal(document.querySelector('script'),null);assert.equal(document.querySelector('[data-member-plan-grid] a[href*="membership/checkout"]'),null);assert.match(document.querySelector('[data-member-status]').textContent,/价格与有效期已核对/);assert.doesNotMatch(document.querySelector('.commerce-center-availability').textContent,/会员订阅周期.*尚未发布/);assert.equal(dom.requests.length,1);assert.equal(dom.requests[0].method,'GET');assert.equal(dom.requests[0].cache,'no-store');assert.equal(localStorage.getItem('paperknow-drafts'),'[{"id":"preserved"}]');dom.window.close();});
test('no published membership keeps clearly labelled reference tiers without inventing a published offer',async()=>{const dom=setup();mountMemberPlans();await settle();assert.equal(document.querySelectorAll('[data-member-product]').length,0);assert.equal(document.querySelectorAll('.purchase-plan').length,3);assert.match(document.querySelector('[data-member-status]').textContent,/正式会员尚未上架.*30 天首发定价方案/);assert.equal(document.querySelector('[data-member-plan-grid] a[href*="membership/pay"]'),null);assert.equal(localStorage.length,0);dom.window.close();});
test('published memberships use one neutral checkout entry regardless of channel availability',async()=>{const dom=setup(),options=catalogue();options.enabled=false;options.channels.forEach(c=>c.ready=false);options.products.push(memberProduct('premium'));dom.window.fetch=async()=>({ok:true,json:async()=>options});mountMemberPlans();await settle();const card=document.querySelector('[data-member-product="premium"]');assert.equal(card.querySelector('a.btn').getAttribute('href'),'#membership/pay?product=premium');assert.equal(card.querySelector('a.btn').textContent.trim(),'确认购买');assert.doesNotMatch(document.querySelector('.dashboard').textContent,/微信|支付宝|支付渠道待开通/);assert.equal(localStorage.length,0);dom.window.close();});
test('late membership catalogue cannot overwrite a subsequent route',async()=>{const dom=setup();let resolveResponse,signal;dom.window.fetch=async(_url,request)=>{signal=request.signal;return new Promise(resolve=>{resolveResponse=resolve;});};mountMemberPlans();await settle();window.history.replaceState(null,'','#assets');window.dispatchEvent(new window.HashChangeEvent('hashchange'));document.querySelector('.dashboard').innerHTML='<p>文件管理页面</p>';const options=catalogue();options.products.push(memberProduct('basic'));resolveResponse({ok:true,json:async()=>options});await settle();assert.equal(signal.aborted,true);assert.equal(document.querySelector('.dashboard').textContent,'文件管理页面');assert.equal(localStorage.length,0);dom.window.close();});
test('membership catalogue timeout preserves references and ignores a late response even if abort is not respected',async()=>{const dom=setup();let timeoutCallback,resolveResponse,signal;const originalSetTimeout=window.setTimeout.bind(window);window.setTimeout=(callback,delay,...args)=>{if(delay===12000){timeoutCallback=callback;return 998;}return originalSetTimeout(callback,delay,...args);};dom.window.fetch=async(_url,request)=>{signal=request.signal;return new Promise(resolve=>{resolveResponse=resolve;});};mountMemberPlans();await settle();timeoutCallback();assert.equal(signal.aborted,true);assert.match(document.querySelector('[data-member-status]').textContent,/正式会员信息暂未取得/);const options=catalogue();options.products.push(memberProduct('basic'));resolveResponse({ok:true,json:async()=>options});await settle();assert.equal(document.querySelectorAll('[data-member-product]').length,0);assert.equal(document.querySelectorAll('.purchase-plan').length,3);assert.equal(localStorage.length,0);dom.window.close();});
test('bundles preserve independent prices and service counts',()=>{const dom=setup();mountCommerce('bundles');assert.equal(document.querySelectorAll('.purchase-plan').length,6);assert.match(document.querySelector('.dashboard').textContent,/¥79/);assert.match(document.querySelector('.dashboard').textContent,/¥9\.9/);assert.match(document.querySelector('.dashboard').textContent,/¥19\.9/);assert.match(document.querySelector('.dashboard').textContent,/¥29\.9/);assert.match(document.querySelector('.dashboard').textContent,/90 天/);assert.ok([...document.querySelectorAll('a')].some(a=>a.getAttribute('href')==='#membership/checkout?kind=bundle&plan=reading&quantity=1'));dom.window.close();});
test('quantity updates a current research reference total, rejects fractions and preserves product',()=>{const dom=setup();mountMemberCheckout('polishing',2,'bundle');assert.equal(document.querySelector('#reference-total').textContent,'¥39.8');const input=document.querySelector('#purchase-quantity');input.value='1.5';input.oninput();assert.equal(document.querySelector('#reference-total').textContent,'—');input.value='3';input.oninput();assert.equal(location.hash,'#membership/checkout?kind=bundle&plan=polishing&quantity=3');assert.equal(document.querySelector('#reference-total').textContent,'¥59.7');assert.equal(document.querySelector('.purchase-confirm button').disabled,true);assert.equal(localStorage.length,0);dom.window.close();});
test('credit packs use the three approved prices without changing account balances',async()=>{const dom=setup();mountCommerce('recharge');await settle();assert.equal(document.querySelector('#credit-custom'),null);assert.deepEqual([...document.querySelectorAll('[data-credit]')].map(b=>Number(b.dataset.credit)),[200,500,1000]);for(const [credits,price] of [[200,20],[500,50],[1000,100]]){document.querySelector(`[data-credit="${credits}"]`).click();assert.equal(document.querySelector('#credit-selected-amount').textContent,String(credits));assert.equal(document.querySelector('#credit-selected-price').textContent,String(price));assert.match(document.querySelector('#credit-summary').textContent,new RegExp(`${credits} 科研积分，支付金额 ¥${price}\\.00`));assert.equal(document.querySelector('#credit-checkout').getAttribute('href'),`#membership/pay?product=credits-${credits}`);}assert.match(document.querySelector('.commerce-credit-use-note').textContent,/任务成功后结算/);assert.equal(localStorage.length,0);dom.window.close();});
test('credit purchase chooses only the product and defers payment method to checkout',async()=>{const dom=setup();mountCommerce('recharge');await settle();document.querySelector('[data-credit="500"]').click();assert.equal(document.querySelectorAll('[data-credit-provider]').length,0);assert.equal(document.querySelector('#credit-checkout').getAttribute('href'),'#membership/pay?product=credits-500');assert.doesNotMatch(document.querySelector('.dashboard').textContent,/微信|支付宝/);assert.equal(location.hash,'#membership/plans');assert.equal(document.querySelectorAll('.payment-qr').length,0);assert.equal(dom.requests.filter(r=>r.method!=='GET').length,0);assert.equal(localStorage.length,0);dom.window.close();});
test('credit catalogue updates visible prices, received credits and exchange information from GET only',async()=>{const dom=setup(),options=catalogue();options.products[0].priceCents=2599;options.products[0].creditAmount=250;options.products[0].entitlement.creditAmount=250;options.products[0].title='<img src=x onerror=alert(1)>';dom.window.fetch=async(url,request)=>{dom.requests.push({url,...request});return {ok:true,json:async()=>options};};mountCommerce('recharge');await settle();assert.equal(document.querySelector('[data-credit="200"] [data-credit-amount]').textContent,'250');assert.equal(document.querySelector('[data-credit="200"] [data-credit-price]').textContent,'25.99');assert.equal(document.querySelector('#credit-selected-amount').textContent,'250');assert.equal(document.querySelector('#credit-selected-price').textContent,'25');assert.equal(document.querySelector('#credit-selected-fraction').textContent,'.99');assert.equal(document.querySelector('#credit-selected-rate').textContent,'¥25.99 = 250 积分');assert.equal(document.querySelector('#credit-rate-label').textContent,'¥25.99 = 250 积分');assert.equal(document.querySelector('#credit-checkout').getAttribute('href'),'#membership/pay?product=credits-200');assert.equal(document.querySelector('img[src="x"]'),null);assert.equal(dom.requests.length,1);assert.equal(dom.requests[0].url,'/api/payments/options');assert.equal(dom.requests[0].method,'GET');assert.equal(localStorage.length,0);dom.window.close();});
test('unlisted credit pack stays unavailable without substituting a different sale product',async()=>{const dom=setup(),options=catalogue();options.products=options.products.filter(p=>p.id!=='credits-200');dom.window.fetch=async()=>({ok:true,json:async()=>options});mountCommerce('recharge');await settle();assert.equal(document.querySelector('[data-credit="200"]').disabled,true);assert.match(document.querySelector('[data-credit="200"] [data-credit-status]').textContent,/暂不可购买/);assert.equal(document.querySelector('#credit-checkout').getAttribute('aria-disabled'),'true');assert.equal(document.querySelector('#credit-checkout').getAttribute('href'),null);assert.equal(document.querySelector('#credit-selected-amount').textContent,'200');assert.equal(document.querySelector('#credit-selected-price').textContent,'—');document.querySelector('[data-credit="500"]').click();assert.equal(document.querySelector('#credit-checkout').getAttribute('href'),'#membership/pay?product=credits-500');assert.equal(localStorage.length,0);dom.window.close();});
test('closed channels are checked only at checkout and do not add choices to credit cards',async()=>{const dom=setup(),options=catalogue();options.enabled=false;options.channels.forEach(c=>c.ready=false);dom.window.fetch=async()=>({ok:true,json:async()=>options});mountCommerce('recharge');await settle();assert.equal(document.querySelectorAll('[data-credit-provider]').length,0);assert.equal(document.querySelector('#credit-checkout').getAttribute('href'),'#membership/pay?product=credits-200');assert.equal(document.querySelector('#credit-checkout').textContent,'确认购买');assert.doesNotMatch(document.querySelector('.dashboard').textContent,/微信|支付宝/);assert.equal(document.querySelectorAll('.payment-qr').length,0);assert.equal(localStorage.length,0);dom.window.close();});
test('failed catalogue read keeps reference amounts and directs to preparation without claiming readiness',async()=>{const dom=setup();dom.window.fetch=async(url,request)=>{dom.requests.push({url,...request});throw new Error('offline');};mountCommerce('recharge');await settle();assert.equal(document.querySelector('#credit-selected-price').textContent,'20');assert.equal(document.querySelector('#credit-price-label').textContent,'参考金额');assert.match(document.querySelector('#credit-summary').textContent,/参考展示/);assert.match(document.querySelector('#credit-rate-label').textContent,/待核对/);assert.equal(document.querySelectorAll('[data-credit-provider]').length,0);assert.equal(document.querySelector('#credit-checkout').textContent,'前往收银台核对');assert.equal(document.querySelector('#credit-checkout').getAttribute('href'),'#membership/pay?product=credits-200');assert.ok(dom.requests.every(r=>r.method==='GET'));assert.equal(localStorage.length,0);dom.window.close();});
test('credit read timeout aborts the request and shows reference pricing instead of endless loading',async()=>{const dom=setup();let timeoutCallback,signal;const originalSetTimeout=window.setTimeout.bind(window);window.setTimeout=(callback,delay,...args)=>{if(delay===12000){timeoutCallback=callback;return 997;}return originalSetTimeout(callback,delay,...args);};dom.window.fetch=async(_url,request)=>{signal=request.signal;return new Promise((_resolve,reject)=>signal.addEventListener('abort',()=>reject(Object.assign(new Error('aborted'),{name:'AbortError'})),{once:true}));};mountCommerce('recharge');await settle();timeoutCallback();await settle();assert.equal(signal.aborted,true);assert.equal(document.querySelector('#credit-checkout').textContent,'前往收银台核对');assert.match(document.querySelector('#credit-rate-label').textContent,/待核对/);assert.match(document.querySelector('#credit-summary').textContent,/参考展示/);assert.equal(localStorage.length,0);dom.window.close();});
test('late catalogue response cannot repaint a different page and route change aborts its read',async()=>{const dom=setup();let resolveResponse,signal;dom.window.fetch=async(_url,request)=>{signal=request.signal;return new Promise(resolve=>{resolveResponse=resolve;});};mountCommerce('recharge');await settle();window.history.replaceState(null,'','#projects');window.dispatchEvent(new window.HashChangeEvent('hashchange'));document.querySelector('.dashboard').innerHTML='<p id="new-page">项目页面</p>';assert.equal(signal.aborted,true);resolveResponse({ok:true,json:async()=>catalogue()});await settle();assert.equal(document.querySelector('.dashboard').textContent,'项目页面');assert.equal(localStorage.length,0);dom.window.close();});
test('repeated credit mounts remove the old listener and ignore an aborted previous response',async()=>{const dom=setup(),pending=[];let listeners=0;const add=window.addEventListener.bind(window),remove=window.removeEventListener.bind(window);window.addEventListener=(name,...args)=>{if(name==='hashchange')listeners++;return add(name,...args);};window.removeEventListener=(name,...args)=>{if(name==='hashchange')listeners--;return remove(name,...args);};dom.window.fetch=async(_url,request)=>new Promise(resolve=>pending.push({resolve,signal:request.signal}));mountCommerce('recharge');await settle();mountCommerce('recharge');await settle();assert.equal(listeners,1);assert.equal(pending[0].signal.aborted,true);pending[1].resolve({ok:true,json:async()=>catalogue()});await settle();const stale=catalogue();stale.products[0].priceCents=9999;stale.products[0].entitlement.creditAmount=999;pending[0].resolve({ok:true,json:async()=>stale});await settle();assert.equal(document.querySelector('#credit-selected-price').textContent,'20');assert.equal(document.querySelector('#credit-selected-amount').textContent,'200');mountCommerce('redeem');assert.equal(listeners,0);assert.equal(pending[1].signal.aborted,true);assert.equal(localStorage.length,0);dom.window.close();});
