test('repeated specialist mounts clean up both readers and switching purchase tabs leaves no stale listeners',async()=>{
 const dom=setup(),pending=[];let listeners=0;
 const add=window.addEventListener.bind(window),remove=window.removeEventListener.bind(window);
 window.addEventListener=(name,...args)=>{if(name==='hashchange')listeners++;return add(name,...args);};
 window.removeEventListener=(name,...args)=>{if(name==='hashchange')listeners--;return remove(name,...args);};
 try{
  window.history.replaceState(null,'','#membership/bundles');window.fetch=async(_url,request)=>new Promise(resolve=>pending.push({resolve,signal:request.signal}));
  mountCommerce('bundles');await settle();assert.equal(pending.length,2);assert.equal(listeners,2);
  mountCommerce('bundles');await settle();assert.equal(pending.length,4);assert.equal(listeners,2);assert.ok(pending.slice(0,2).every(request=>request.signal.aborted));
  const fresh=catalogue();fresh.products.push(bundleProduct('bundle-dual',{title:'新挂载商品'}));for(const request of pending.slice(2))request.resolve({ok:true,json:async()=>fresh});await settle();
  const old=catalogue();old.products.push(bundleProduct('bundle-dual',{title:'旧挂载商品',priceCents:9999}));for(const request of pending.slice(0,2))request.resolve({ok:true,json:async()=>old});await settle();
  assert.match(document.querySelector('[data-revision-bundle-offers]').textContent,/新挂载商品/);assert.doesNotMatch(document.querySelector('[data-revision-bundle-offers]').textContent,/旧挂载商品/);assert.equal(document.querySelectorAll('[data-revision-bundle-offers]').length,1);
  mountCommerce('redeem');assert.equal(listeners,0);assert.ok(pending.every(request=>request.signal.aborted));assert.equal(localStorage.length,0);
 }finally{dom.window.close();}
});

